import { isArgumentValueToken, isOptionWithInlineValue } from './token_checks.mjs';

function usageLine(programName) {
  return `usage: ${programName} [-h] --a A`;
}

export function formatHelp(programName) {
  return `${usageLine(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

export function formatError(programName, message) {
  return `${usageLine(programName)}\n${programName}: error: ${message}\n`;
}

export function parseCommandLine(argv) {
  let aValue;
  const extras = [];
  let afterDoubleDash = false;
  let index = 0;

  while (index < argv.length) {
    const token = argv[index];

    if (!afterDoubleDash && (token === '-h' || token === '--help')) {
      return {
        kind: 'help',
      };
    }

    if (!afterDoubleDash && token === '--') {
      afterDoubleDash = true;
      extras.push(token);
      index += 1;
      continue;
    }

    if (!afterDoubleDash && token === '--a') {
      const nextToken = argv[index + 1];

      if (!isArgumentValueToken(nextToken)) {
        return {
          kind: 'error',
          message: 'argument --a: expected one argument',
        };
      }

      aValue = nextToken;
      index += 2;
      continue;
    }

    if (!afterDoubleDash && isOptionWithInlineValue(token, '--a')) {
      aValue = token.slice(4);
      index += 1;
      continue;
    }

    extras.push(token);
    index += 1;
  }

  if (aValue === undefined) {
    return {
      kind: 'error',
      message: 'the following arguments are required: --a',
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'success',
    aValue,
  };
}

