function isDigit(character) {
  return character >= '0' && character <= '9';
}

export function isNegativeNumberToken(token) {
  if (token === undefined || token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDot = false;
  let digitsBeforeDot = 0;
  let digitsAfterDot = 0;

  while (index < token.length) {
    const character = token[index];

    if (isDigit(character)) {
      if (sawDot) {
        digitsAfterDot += 1;
      } else {
        digitsBeforeDot += 1;
      }

      index += 1;
      continue;
    }

    if (character === '.' && !sawDot) {
      sawDot = true;
      index += 1;
      continue;
    }

    return false;
  }

  if (sawDot) {
    return digitsAfterDot > 0;
  }

  return digitsBeforeDot > 0;
}

export function isArgumentValueToken(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '--') {
    return false;
  }

  if (token.length === 0) {
    return true;
  }

  if (token[0] !== '-') {
    return true;
  }

  return isNegativeNumberToken(token);
}

export function isOptionWithInlineValue(token, optionName) {
  if (token === undefined) {
    return false;
  }

  if (!token.startsWith(optionName)) {
    return false;
  }

  if (token.length <= optionName.length) {
    return false;
  }

  return token[optionName.length] === '=';
}

