import { formatError, formatHelp, parseCommandLine } from './lib/cli/parser.mjs';
import { getProgramName } from './lib/cli/program_name.mjs';
import { runYamlPipeline } from './lib/runtime/yaml_bridge.mjs';

function main() {
  const programName = getProgramName(process.argv[1]);
  const parsed = parseCommandLine(process.argv.slice(2));

  if (parsed.kind === 'help') {
    process.stdout.write(formatHelp(programName));
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(formatError(programName, parsed.message));
    return 2;
  }

  const result = runYamlPipeline(parsed.aValue);

  if (result.stdout.length > 0) {
    process.stdout.write(result.stdout);
  }

  if (result.stderr.length > 0) {
    process.stderr.write(result.stderr);
  }

  return result.status;
}

process.exitCode = main();

